package sfz.batch.l13.demo

import java.time.LocalDate
import kotlin.random.Random

/**
 * One night where the load task's worker dies right after it wrote its result, run with an
 * appending load and with an overwriting load. Then 90 nights with random crashes of that kind.
 */
fun main() {
    val day = LocalDate.of(2026, 11, 6)
    for ((name, load) in listOf("append (INSERT INTO)" to append, "overwrite the partition" to overwrite)) {
        val w = Warehouse()
        println("load = $name")
        runDay(w, day, load, crashes = 1) { println("  $it") }
        println("  the source says %,d cents".format(payments(day).sum()))
    }

    val days = (0 until 90).map { LocalDate.of(2026, 8, 9).plusDays(it.toLong()) }
    val rnd = Random(7)
    val crashes = days.associateWith { var n = 0; while (n < 2 && rnd.nextDouble() < 0.2) n++; n }
    val truth = days.sumOf { payments(it).sum() }
    println("90 nights, each load crashing after its write with chance 20% (sometimes twice): ${crashes.values.count { it > 0 }} nights hit")
    for ((name, load) in listOf("append" to append, "overwrite" to overwrite)) {
        val w = Warehouse()
        days.forEach { runDay(w, it, load, crashes.getValue(it)) }
        val wrong = days.count { w.read("daily_totals", it) != listOf(payments(it).sum()) }
        println("  %-9s total %,15d cents, %+.1f%% against the source, %d wrong days".format(name, w.total("daily_totals"), 100.0 * (w.total("daily_totals") - truth) / truth, wrong))
    }
}

package sfz.batch.l13.demo

/**
 * One stage of 200 tasks on 20 task slots, on virtual time, run four ways. In the first case one
 * machine (two slots) has a failing disk and runs 30 times slower. In the second, one task has 30
 * times the data of the others (a skewed key). Each case runs without and with speculation, using
 * Spark's rule: once 90% of the stage's tasks are done, a task running longer than 3 times the
 * median task time gets a copy on a free slot, and whichever copy finishes first wins.
 */
fun main() {
    println("%-34s %18s %18s".format("stage of 200 tasks, 20 slots", "no speculation", "speculation"))
    for ((name, slowSlots, bigTask) in listOf(
        Triple("one slow machine (2 slots, 30x)", setOf(0, 1), -1),
        Triple("one skewed task (30x the data)", emptySet(), 137),
    )) {
        val plain = stage(slowSlots, bigTask, speculate = false)
        val spec = stage(slowSlots, bigTask, speculate = true)
        println("%-34s %15.1f s %15.1f s   (%d speculative %s)".format(name, plain.first, spec.first, spec.second, if (spec.second == 1) "copy" else "copies"))
    }
    println("a healthy stage takes %.1f s".format(stage(emptySet(), -1, speculate = false).first))
}

/** Returns the stage's finish time in seconds and the number of speculative copies launched. */
private fun stage(slowSlots: Set<Int>, bigTask: Int, speculate: Boolean): Pair<Double, Int> {
    val tasks = 200
    val slots = 20
    val work = DoubleArray(tasks) { if (it == bigTask) 30.0 * 4 else 4.0 }       // seconds on a healthy slot
    val speed = DoubleArray(slots) { if (it in slowSlots) 1.0 / 30 else 1.0 }
    data class Copy(val task: Int, val slot: Int, val start: Double)
    val running = mutableListOf<Copy>()
    val done = BooleanArray(tasks)
    val durations = mutableListOf<Double>()
    val busy = BooleanArray(slots)
    var next = 0
    var copies = 0
    var t = 0.0
    val dt = 0.1
    while (done.any { !it }) {
        // start pending tasks on free slots, lowest slot first
        for (s in 0 until slots) if (!busy[s] && next < tasks) { running += Copy(next++, s, t); busy[s] = true }
        // speculation check, as Spark does every 100 ms
        if (speculate && next == tasks && done.count { it } >= 0.9 * tasks) {
            val median = durations.sorted()[durations.size / 2]
            for (c in running.toList()) {
                val alreadyCopied = running.count { it.task == c.task } > 1
                if (!alreadyCopied && t - c.start > 3 * median) {
                    val free = (0 until slots).firstOrNull { !busy[it] } ?: continue
                    running += Copy(c.task, free, t); busy[free] = true; copies++
                }
            }
        }
        t += dt
        // finish copies whose work is done; the first copy of a task to finish wins, the other is killed
        for (c in running.toList()) {
            if (c !in running) continue
            if ((t - c.start) * speed[c.slot] >= work[c.task] - 1e-9) {
                done[c.task] = true
                durations += t - c.start
                for (o in running.filter { it.task == c.task }) { running.remove(o); busy[o.slot] = false }
            }
        }
    }
    return t to copies
}

package sfz.batch.l13.demo

import java.time.LocalDate

/**
 * A year of history backfilled with the daily-totals pipeline (20 minutes a run), with Airflow's
 * `--max-active-runs` at 1, 4 and 16, oldest first and with `--run-backwards`. Then the same backfill
 * run a second time, the way `--reprocess-behavior completed` would, with each kind of load.
 */
fun main() {
    val days = (0 until 365).map { LocalDate.of(2025, 11, 7).plusDays(it.toLong()) }
    fun hours(m: Long) = "%.1f h".format(m / 60.0)
    println("365 daily runs of 20 minutes:")
    for (active in listOf(1, 4, 16)) {
        val (end, firstWeekDone) = backfill(days, active, backwards = false)
        val (endB, newestWeekDone) = backfill(days, active, backwards = true)
        println("  max active runs %2d: done after %7s; the newest week is ready after %7s, or %7s with run backwards".format(
            active, hours(end), hours(firstWeekDone), hours(newestWeekDone)))
        check(end == endB)
    }
    for ((name, load) in listOf("append" to append, "overwrite" to overwrite)) {
        val w = Warehouse()
        repeat(2) { days.forEach { runDay(w, it, load, crashes = 0) } }
        val truth = days.sumOf { payments(it).sum() }
        println("backfill run twice, load = %-9s total is %.2f times the source".format(name, w.total("daily_totals").toDouble() / truth))
    }
}

/** Returns when the whole backfill ends, and when the newest 7 days are all done, in minutes. */
private fun backfill(days: List<LocalDate>, active: Int, backwards: Boolean): Pair<Long, Long> {
    val freeAt = LongArray(active)
    val ends = mutableMapOf<LocalDate, Long>()
    for (d in if (backwards) days.reversed() else days) {
        val slot = freeAt.indices.minBy { freeAt[it] }
        freeAt[slot] += 20
        ends[d] = freeAt[slot]
    }
    return ends.values.max() to days.takeLast(7).maxOf { ends.getValue(it) }
}

