from datetime import datetime, timedelta
from airflow.sdk import dag, task

@dag(schedule="@daily", start_date=datetime(2026, 1, 1), catchup=False,
     default_args={"retries": 2, "retry_delay": timedelta(minutes=5)})
def daily_totals():
    @task
    def import_settlement_file(ds=None): ...   # reads the acquirer's file for day ds

    @task
    def load_totals(ds=None): ...              # the DELETE + INSERT above, for day ds

    import_settlement_file() >> load_totals()

daily_totals()

